// ❌ OLD: Allocating fresh objects, arrays, and strings on every
// request. Each request fills the young generation with garbage that
// dies immediately — forcing constant scavenges. At high QPS the
// minor-GC frequency rises, consuming CPU on the main thread and
// adding latency spikes.
function handle(req) {
  // ❌ OLD: new array + new objects + string splits per request
  const parts = req.body.split(','); // allocates a string array
  const result = { data: parts.map(Number), ts: Date.now() };
  return JSON.stringify(result); // another big string
}

// Every request: ~5-10 short-lived allocations. Under 10k req/s that
// is 50-100k allocations/s the scavenger must process.

// ✅ NEW: Reduce young-gen pressure by reusing buffers and avoiding
// needless intermediate allocations. The GC still runs, but less
// often and with smaller nurseries to process.
const { Buffer } = require('node:buffer');

// ✅ NEW: reuse a preallocated buffer for output instead of building
// new strings per request (where the format allows)
const out = Buffer.alloc(256);

function handle(req) {
  // ✅ NEW: avoid split() when a simple parse suffices
  const data = parseNumbers(req.body); // no temp string arrays

  // ✅ NEW: write into the reused buffer rather than JSON.stringify
  const len = out.write(`{"data":${data.join(',')}}`);
  return out.subarray(0, len);
}

